changes.sections/rich-text-wrappers.liquid:
{%- assign wrapper = section.settings.wrapper_tag | default: 'div' -%}
<div class="rich-text rich-text--{{ section.settings.text_alignment }}" style="padding-top: {{ section.settings.padding_top }}px; padding-bottom: {{ section.settings.padding_bottom }}px;">
  {%- if section.settings.use_container -%}<div class="page-width">{%- endif -%}
  <{{ wrapper }} class="rich-text__blocks">
    {%- for block in section.blocks -%}
      {%- case block.type -%}
        {%- when 'heading' -%}
          <{{ block.settings.heading_size }} class="rich-text__heading" {{ block.shopify_attributes }}>{{ block.settings.heading }}</{{ block.settings.heading_size }}>
        {%- when 'text' -%}
          <div class="rich-text__text rte" {{ block.shopify_attributes }}>{{ block.settings.text }}</div>
        {%- when 'button' -%}
          {%- if block.settings.button_label != blank -%}
            <div class="rich-text__buttons" {{ block.shopify_attributes }}>
              {%- if block.settings.button_link != blank -%}<a class="button" href="{{ block.settings.button_link }}">{{ block.settings.button_label | escape }}</a>{%- else -%}<span class="button button--disabled">{{ block.settings.button_label | escape }}</span>{%- endif -%}
            </div>
          {%- endif -%}
      {%- endcase -%}
    {%- endfor -%}
  </{{ wrapper }}>
  {%- if section.settings.use_container -%}</div>{%- endif -%}
</div>

{% schema %}
